  add("algebra", "b3", 7, [{"type":"regular","q":"Find the vertex of \\(f(x) = x^2 + 8x + 10\\).","answer":"\\((-4, -6)\\)","solution":"Vertex \\(x = -\\frac{b}{2a} = -\\frac{8}{2} = -4\\); \\(f(-4) = 16 - 32 + 10 = -6\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = (x-7)^2 + 3\\).","answer":"\\((7, 3)\\)","solution":"Vertex form \\((x-h)^2 + k\\) has vertex \\((h, k) = (7, 3)\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = -2(x+1)^2 + 5\\).","answer":"\\((-1, 5)\\)","solution":"Vertex form has vertex \\((h, k) = (-1, 5)\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = x^2 - 10x + 20\\).","answer":"\\((5, -5)\\)","solution":"\\(x = -\\frac{-10}{2} = 5\\); \\(f(5) = 25 - 50 + 20 = -5\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = 2x^2 + 8x + 1\\).","answer":"\\((-2, -7)\\)","solution":"\\(x = -\\frac{8}{4} = -2\\); \\(f(-2) = 8 - 16 + 1 = -7\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = -(x-3)^2 - 2\\).","answer":"\\((3, -2)\\)","solution":"Vertex form \\(-(x-h)^2 + k\\) has vertex \\((h, k) = (3, -2)\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = x^2 + 6x + 15\\).","answer":"\\((-3, 6)\\)","solution":"\\(x = -\\frac{6}{2} = -3\\); \\(f(-3) = 9 - 18 + 15 = 6\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = 3(x+2)^2 - 1\\).","answer":"\\((-2, -1)\\)","solution":"Vertex form has vertex \\((h, k) = (-2, -1)\\)."},{"type":"word","q":"A ball's height is \\(h(t) = -16t^2 + 64t + 10\\). At what time is the maximum height?","answer":"\\(t = 2\\) s","solution":"Vertex time: \\(t = -\\frac{64}{2(-16)} = 2\\)."},{"type":"word","q":"A profit function is \\(P(x) = -x^2 + 14x - 30\\). What \\(x\\) maximizes profit?","answer":"\\(x = 7\\)","solution":"Vertex \\(x = -\\frac{14}{2(-1)} = 7\\)."},{"type":"word","q":"A parabola is \\(y = 2(x-5)^2 + 8\\). What is the vertex?","answer":"\\((5, 8)\\)","solution":"Vertex form gives \\((h, k) = (5, 8)\\)."},{"type":"word","q":"An arch is \\(y = -0.1(x-20)^2 + 40\\). What is the maximum height?","answer":"40 units","solution":"The vertex is \\((20, 40)\\), so max height is 40."},{"type":"word","q":"Revenue is \\(R(p) = -3p^2 + 30p + 5\\). What price maximizes revenue?","answer":"\\(p = 5\\)","solution":"Vertex \\(p = -\\frac{30}{2(-3)} = 5\\)."},{"type":"word","q":"A distance function is \\(d(t) = (t-4)^2 - 9\\). What is the vertex?","answer":"\\((4, -9)\\)","solution":"Vertex form has vertex \\((h, k) = (4, -9)\\)."},{"type":"word","q":"A parabola is \\(y = x^2 - 12x + 50\\). Find the vertex.","answer":"\\((6, 14)\\)","solution":"\\(x = -\\frac{-12}{2} = 6\\); \\(f(6) = 36 - 72 + 50 = 14\\)."}]);
  add("algebra", "b3", 8, [{"type":"regular","q":"Find the axis of symmetry for \\(y = x^2 - 6x + 5\\).","answer":"\\(x = 3\\)","solution":"Axis: \\(x = -\\frac{b}{2a} = -\\frac{-6}{2} = 3\\)."},{"type":"regular","q":"Does \\(y = -5x^2 + 3\\) open up or down?","answer":"Down","solution":"Since \\(a = -5 < 0\\), it opens downward."},{"type":"regular","q":"Find the \\(y\\)-intercept of \\(y = x^2 + 4x - 3\\).","answer":"\\(-3\\)","solution":"The \\(y\\)-intercept is \\(c\\) in \\(ax^2 + bx + c\\)."},{"type":"regular","q":"Find the axis of symmetry for \\(y = 2x^2 + 12x + 1\\).","answer":"\\(x = -3\\)","solution":"Axis: \\(x = -\\frac{12}{2(2)} = -3\\)."},{"type":"regular","q":"Does \\(y = 0.5x^2 - 2\\) open up or down?","answer":"Up","solution":"Since \\(a = 0.5 > 0\\), it opens upward."},{"type":"regular","q":"Find the \\(y\\)-intercept of \\(y = 3x^2 - 5x + 7\\).","answer":"\\(7\\)","solution":"The \\(y\\)-intercept is \\(c = 7\\)."},{"type":"regular","q":"Find the axis of symmetry for \\(y = -x^2 + 8x - 2\\).","answer":"\\(x = 4\\)","solution":"Axis: \\(x = -\\frac{8}{2(-1)} = 4\\)."},{"type":"regular","q":"Does \\(y = -2x^2 + 6x\\) open up or down?","answer":"Down","solution":"Since \\(a = -2 < 0\\), it opens downward."},{"type":"word","q":"A parabola is \\(y = x^2 - 10x + 24\\). What is the axis of symmetry?","answer":"\\(x = 5\\)","solution":"Axis: \\(x = -\\frac{-10}{2} = 5\\)."},{"type":"word","q":"A bridge arch is \\(y = -0.02x^2 + 2x\\). Find the axis of symmetry.","answer":"\\(x = 50\\)","solution":"Axis: \\(x = -\\frac{2}{2(-0.02)} = 50\\)."},{"type":"word","q":"A projectile is \\(h(t) = -16t^2 + 80t\\). When is the maximum height reached?","answer":"\\(t = 2.5\\) s","solution":"Axis of symmetry: \\(t = -\\frac{80}{2(-16)} = 2.5\\)."},{"type":"word","q":"A profit function is \\(P(x) = -2x^2 + 16x - 10\\). What is the axis of symmetry?","answer":"\\(x = 4\\)","solution":"Axis: \\(x = -\\frac{16}{2(-2)} = 4\\)."},{"type":"word","q":"A parabola opens upward with vertex at \\((3, -5)\\). What is the axis of symmetry?","answer":"\\(x = 3\\)","solution":"The axis of symmetry passes through the vertex's \\(x\\)-coordinate."},{"type":"word","q":"A distance function is \\(d(t) = t^2 - 14t + 50\\). Find the axis of symmetry.","answer":"\\(t = 7\\)","solution":"Axis: \\(t = -\\frac{-14}{2} = 7\\)."},{"type":"word","q":"A revenue model is \\(R(p) = -4p^2 + 24p + 5\\). What is the axis of symmetry?","answer":"\\(p = 3\\)","solution":"Axis: \\(p = -\\frac{24}{2(-4)} = 3\\)."}]);
  add("algebra", "b3", 9, [{"type":"regular","q":"A rectangular pen has width \\(x\\) and length \\(x + 5\\). If area is 36, find \\(x\\).","answer":"\\(x = 4\\)","solution":"\\(x(x+5) = 36 \\Rightarrow x^2 + 5x - 36 = 0 \\Rightarrow (x+9)(x-4) = 0\\)."},{"type":"regular","q":"A number is 3 more than another. Their product is 40. Find the smaller number.","answer":"\\(5\\)","solution":"\\(x(x+3) = 40 \\Rightarrow x^2 + 3x - 40 = 0\\)."},{"type":"regular","q":"Find two consecutive integers whose product is 72.","answer":"8 and 9","solution":"\\(x(x+1) = 72 \\Rightarrow x^2 + x - 72 = 0\\)."},{"type":"regular","q":"A rectangle has area 48 and length 2 more than width. Find the width.","answer":"6","solution":"\\(w(w+2) = 48 \\Rightarrow w^2 + 2w - 48 = 0\\)."},{"type":"regular","q":"A number squared minus 7 times the number equals 18. Find the number.","answer":"9 or -2","solution":"\\(x^2 - 7x = 18 \\Rightarrow x^2 - 7x - 18 = 0\\)."},{"type":"regular","q":"A rectangular field has area 60 and perimeter 32. Find the length.","answer":"10","solution":"Length \\(l\\) and width \\(w\\): \\(lw = 60\\) and \\(2l + 2w = 32\\)."},{"type":"regular","q":"Two numbers sum to 10 and their product is 21. Find the numbers.","answer":"3 and 7","solution":"\\(x + y = 10\\) and \\(xy = 21\\); solve \\(x(10-x) = 21\\)."},{"type":"word","q":"A ball is thrown upward with \\(h(t) = -16t^2 + 64t + 4\\). When does it return to 4 ft?","answer":"\\(t = 4\\) s","solution":"Solve \\(-16t^2 + 64t + 4 = 4 \\Rightarrow -16t^2 + 64t = 0\\)."},{"type":"word","q":"A garden plot is rectangular with area \\(x^2 + 8x = 0\\) when \\(x = 0\\). If area is 20, what is \\(x\\)?","answer":"\\(x = 2\\)","solution":"\\(x(x+8) = 20 \\Rightarrow x^2 + 8x - 20 = 0\\)."},{"type":"word","q":"A projectile reaches height \\(h(t) = -4.9t^2 + 20t\\). When is \\(h = 0\\)?","answer":"\\(t = 0\\) or \\(t \\approx 4.08\\) s","solution":"Solve \\(-4.9t^2 + 20t = 0 \\Rightarrow t(-4.9t + 20) = 0\\)."},{"type":"word","q":"A company's profit is \\(P(x) = -x^2 + 30x - 200\\). When is profit zero?","answer":"\\(x = 10, 20\\)","solution":"Solve \\(-x^2 + 30x - 200 = 0\\) using the quadratic formula."},{"type":"word","q":"A rectangular frame has outer area \\(x^2 + 10x\\) and inner area 20. If total area is 45, find \\(x\\).","answer":"\\(x = 3.5\\)","solution":"Set up and solve \\(x^2 + 10x - 20 = 45\\)."},{"type":"word","q":"Two consecutive odd integers have product 99. Find them.","answer":"9 and 11","solution":"\\(x(x+2) = 99 \\Rightarrow x^2 + 2x - 99 = 0\\)."},{"type":"word","q":"A rectangular pool has dimensions \\((x+3)\\) by \\(x\\) with area 70. Find \\(x\\).","answer":"\\(x = 7\\)","solution":"\\(x(x+3) = 70 \\Rightarrow x^2 + 3x - 70 = 0\\)."},{"type":"word","q":"An object falls with \\(h(t) = -5t^2 + 50\\). When does it hit the ground?","answer":"\\(t \\approx 3.16\\) s","solution":"Solve \\(-5t^2 + 50 = 0 \\Rightarrow t^2 = 10\\)."}]);
  add("algebra", "b3", 10, [{"type":"regular","q":"For \\(y > x^2 + 1\\), is the boundary solid or dashed?","answer":"Dashed","solution":"Strict inequality \\(>\\) uses a dashed curve."},{"type":"regular","q":"For \\(y \\le -x^2 + 5\\), shade above or below?","answer":"Below","solution":"For \\(y \\le\\) (less than or equal), shade below the parabola."},{"type":"regular","q":"Is \\((0, 0)\\) in the solution region for \\(y \\ge x^2 - 1\\)?","answer":"Yes","solution":"Check: \\(0 \\ge 0 - 1 = -1\\) is true."},{"type":"regular","q":"For \\(y < x^2\\), is the boundary solid or dashed?","answer":"Dashed","solution":"Strict inequality \\(<\\) uses a dashed curve."},{"type":"regular","q":"Is \\((1, 2)\\) in the solution region for \\(y > x^2\\)?","answer":"Yes","solution":"Check: \\(2 > 1^2 = 1\\) is true."},{"type":"regular","q":"For \\(y \\ge (x-2)^2 + 3\\), shade above or below?","answer":"Above","solution":"For \\(y \\ge\\) (greater than or equal), shade above the parabola."},{"type":"regular","q":"Is \\((0, 5)\\) in the solution for \\(y \\le -x^2 + 4\\)?","answer":"No","solution":"Check: \\(5 \\le 0 + 4 = 4\\) is false."},{"type":"regular","q":"For \\(y \\ge x^2 + 2x\\), is the boundary solid or dashed?","answer":"Solid","solution":"Non-strict inequality \\(\\ge\\) uses a solid curve."},{"type":"word","q":"A region is defined by \\(y > x^2 - 4\\). Is the point \\((0, -3)\\) included?","answer":"No","solution":"Check: \\(-3 > 0 - 4 = -4\\) is true, so yes it is included."},{"type":"word","q":"A region is \\(y \\le -x^2 + 10x\\). Is \\((5, 25)\\) included?","answer":"Yes","solution":"Check: \\(25 \\le -(25) + 50 = 25\\) is true."},{"type":"word","q":"For the inequality \\(y \\ge (x-3)^2 - 5\\), is \\((3, -5)\\) in the solution?","answer":"Yes","solution":"Check: \\(-5 \\ge 0 - 5 = -5\\) is true."},{"type":"word","q":"A constraint is \\(y < x^2 + 6x + 9\\). Is the origin included?","answer":"Yes","solution":"Check: \\(0 < 0 + 0 + 9 = 9\\) is true."},{"type":"word","q":"For \\(y \\le -2x^2 + 8\\), is the boundary solid or dashed?","answer":"Solid","solution":"Non-strict inequality \\(\\le\\) uses a solid curve."},{"type":"word","q":"A region is \\(y > (x+1)^2 - 4\\). Is \\((-1, 0)\\) included?","answer":"Yes","solution":"Check: \\(0 > 0 - 4 = -4\\) is true."},{"type":"word","q":"For \\(y \\ge x^2 - 2x - 3\\), is the point \\((2, -5)\\) in the solution?","answer":"No","solution":"Check: \\(-5 \\ge 4 - 4 - 3 = -3\\) is false."}]);
  addCum("algebra", "b3", [{"type":"regular","q":"Factor \\(x^2 + 14x + 45\\).","answer":"\\((x+5)(x+9)\\)","solution":"Find two numbers that multiply to 45 and add to 14: 5 and 9."},{"type":"regular","q":"Simplify \\(\\sqrt{-100}\\).","answer":"\\(10i\\)","solution":"\\(\\sqrt{-100} = \\sqrt{100} \\cdot i = 10i\\)."},{"type":"regular","q":"Complete the square: \\(x^2 - 16x\\).","answer":"\\((x-8)^2 - 64\\)","solution":"Half of -16 is -8; square it to get 64."},{"type":"regular","q":"Solve \\(x^2 - 7x + 12 = 0\\) using the quadratic formula.","answer":"\\(x = 3, 4\\)","solution":"\\(x = \\frac{7 \\pm \\sqrt{49-48}}{2} = \\frac{7 \\pm 1}{2}\\)."},{"type":"regular","q":"Find the vertex of \\(f(x) = x^2 - 12x + 40\\).","answer":"\\((6, 4)\\)","solution":"\\(x = -\\frac{-12}{2} = 6\\); \\(f(6) = 36 - 72 + 40 = 4\\)."},{"type":"regular","q":"Find the axis of symmetry for \\(y = 3x^2 - 18x + 5\\).","answer":"\\(x = 3\\)","solution":"Axis: \\(x = -\\frac{-18}{2(3)} = 3\\)."},{"type":"regular","q":"Does \\(y = -4x^2 + 2\\) open up or down?","answer":"Down","solution":"Since \\(a = -4 < 0\\), it opens downward."},{"type":"regular","q":"For \\(y \\ge x^2 - 3\\), is the boundary solid or dashed?","answer":"Solid","solution":"Non-strict inequality \\(\\ge\\) uses a solid curve."},{"type":"regular","q":"Solve \\(x^2 + 8x + 16 = 0\\).","answer":"\\(x = -4\\)","solution":"\\((x+4)^2 = 0\\) gives \\(x = -4\\) (double root)."},{"type":"regular","q":"What is \\(i^{12}\\)?","answer":"\\(1\\)","solution":"\\(i^{12} = (i^4)^3 = 1^3 = 1\\)."},{"type":"word","q":"A rectangular garden has area \\(x^2 + 9x + 18\\). One side is \\(x + 3\\). Find the other.","answer":"\\(x+6\\)","solution":"Factor: \\(x^2 + 9x + 18 = (x+3)(x+6)\\)."},{"type":"word","q":"A projectile's height is \\(h(t) = -16t^2 + 96t + 10\\). Find the time at maximum height.","answer":"\\(t = 3\\) s","solution":"Vertex time: \\(t = -\\frac{96}{2(-16)} = 3\\)."},{"type":"word","q":"A ball is thrown upward with \\(h(t) = -16t^2 + 80t\\). When does it return to ground level?","answer":"\\(t = 5\\) s","solution":"Solve \\(-16t^2 + 80t = 0 \\Rightarrow t(-16t+80) = 0\\)."},{"type":"word","q":"A rectangular field has length 5 more than width and area 84. Find the width.","answer":"\\(7\\)","solution":"\\(w(w+5) = 84 \\Rightarrow w^2 + 5w - 84 = 0\\)."},{"type":"word","q":"A profit model is \\(P(x) = -x^2 + 20x - 75\\). When is profit zero?","answer":"\\(x = 5, 15\\)","solution":"Solve \\(-x^2 + 20x - 75 = 0\\) using the quadratic formula."},{"type":"word","q":"A bridge arch is \\(y = -0.05(x-30)^2 + 45\\). What is the maximum height?","answer":"45 units","solution":"The vertex is \\((30, 45)\\), so max height is 45."},{"type":"word","q":"An object falls with \\(h(t) = -5t^2 + 100\\). When does it hit the ground?","answer":"\\(t \\approx 4.47\\) s","solution":"Solve \\(-5t^2 + 100 = 0 \\Rightarrow t^2 = 20\\)."},{"type":"word","q":"A quadratic has no real solutions. What can you say about its discriminant?","answer":"It is negative","solution":"If \\(b^2 - 4ac < 0\\), there are no real solutions."},{"type":"word","q":"A region is defined by \\(y \\le x^2 - 6x + 5\\). Is \\((3, -5)\\) included?","answer":"Yes","solution":"Check: \\(-5 \\le 9 - 18 + 5 = -4\\) is true."},{"type":"word","q":"Two consecutive integers have product 56. Find the larger one.","answer":"8","solution":"\\(x(x+1) = 56 \\Rightarrow x^2 + x - 56 = 0\\)."},{"type":"word","q":"Rewrite \\(f(x) = x^2 - 20x + 110\\) in vertex form.","answer":"\\(f(x) = (x-10)^2 + 10\\)","solution":"Complete the square: \\((x-10)^2 - 100 + 110 = (x-10)^2 + 10\\)."},{"type":"word","q":"A revenue function is \\(R(p) = -2p^2 + 40p\\). Find the price that maximizes revenue.","answer":"\\(p = 10\\)","solution":"Vertex: \\(p = -\\frac{40}{2(-2)} = 10\\)."},{"type":"word","q":"Solve \\(x^2 + 5x - 24 = 0\\) by factoring.","answer":"\\(x = 3, -8\\)","solution":"\\((x-3)(x+8) = 0\\) gives \\(x = 3, -8\\)."}]);
  add("algebra", "b4", 0, [{"type":"regular","q":"What is a rational expression in simplest terms?","answer":"A fraction where the numerator and denominator are polynomials.","solution":"A rational expression is defined as the quotient of two polynomials."},{"type":"regular","q":"For what value of \\(x\\) is \\(\\dfrac{x+5}{x+1}\\) undefined?","answer":"\\(x = -1\\)","solution":"The expression is undefined when the denominator equals zero: \\(x+1=0\\)."},{"type":"regular","q":"For what values of \\(x\\) is \\(\\dfrac{3x}{x^2 - 9}\\) undefined?","answer":"\\(x = \\pm 3\\)","solution":"Set \\(x^2 - 9 = 0\\), which factors as \\((x-3)(x+3)=0\\)."},{"type":"regular","q":"For what value is \\(\\dfrac{2x-1}{x-4}\\) undefined?","answer":"\\(x = 4\\)","solution":"The denominator \\(x-4=0\\) when \\(x=4\\)."},{"type":"regular","q":"Is \\(\\dfrac{x^2+1}{x^2+1}\\) ever undefined?","answer":"No, never undefined.","solution":"The denominator \\(x^2+1\\) is always positive for all real \\(x\\)."},{"type":"regular","q":"For what values of \\(x\\) is \\(\\dfrac{5}{x^2 - 16}\\) undefined?","answer":"\\(x = \\pm 4\\)","solution":"Factor: \\(x^2-16=(x-4)(x+4)=0\\) gives \\(x=4\\) or \\(x=-4\\)."},{"type":"regular","q":"For what value is \\(\\dfrac{x}{x^2 + 5}\\) undefined?","answer":"Never undefined.","solution":"The denominator \\(x^2+5\\) is always positive."},{"type":"regular","q":"For what values of \\(x\\) is \\(\\dfrac{7x}{x^2 - 2x}\\) undefined?","answer":"\\(x = 0\\) and \\(x = 2\\)","solution":"Factor the denominator: \\(x^2-2x=x(x-2)=0\\)."},{"type":"word","q":"A recipe calls for \\(\\dfrac{x-1}{x}\\) cups of sugar. For what value of \\(x\\) is this undefined?","answer":"\\(x = 0\\)","solution":"The denominator \\(x\\) equals zero when \\(x=0\\)."},{"type":"word","q":"The speed of a car is \\(\\dfrac{x^2}{x-5}\\) mph. For what value is this expression undefined?","answer":"\\(x = 5\\)","solution":"Set the denominator \\(x-5=0\\) to find \\(x=5\\)."},{"type":"word","q":"A ratio of water to salt is \\(\\dfrac{2x}{x^2-4}\\). For what values is it undefined?","answer":"\\(x = \\pm 2\\)","solution":"Factor: \\(x^2-4=(x-2)(x+2)=0\\) gives \\(x=2\\) or \\(x=-2\\)."},{"type":"word","q":"The cost per item is \\(\\dfrac{100}{x-10}\\) dollars. For what value is it undefined?","answer":"\\(x = 10\\)","solution":"The denominator \\(x-10=0\\) when \\(x=10\\)."},{"type":"word","q":"A concentration is \\(\\dfrac{x+3}{x^2-9}\\). For what values is it undefined?","answer":"\\(x = \\pm 3\\)","solution":"Factor: \\(x^2-9=(x-3)(x+3)=0\\)."},{"type":"word","q":"A recipe uses \\(\\dfrac{x}{x^2+1}\\) teaspoons of salt. Is this ever undefined?","answer":"No.","solution":"The denominator \\(x^2+1\\) is always positive."},{"type":"word","q":"The efficiency ratio is \\(\\dfrac{x+2}{(x-1)(x+5)}\\). For what values is it undefined?","answer":"\\(x = 1\\) and \\(x = -5\\)","solution":"The denominator is zero when \\(x-1=0\\) or \\(x+5=0\\)."}]);
  add("algebra", "b4", 1, [{"type":"regular","q":"Rewrite \\(\\dfrac{5}{7}\\) with denominator 21.","answer":"\\(\\dfrac{15}{21}\\)","solution":"Multiply numerator and denominator by 3: \\(\\dfrac{5 \\cdot 3}{7 \\cdot 3}\\)."},{"type":"regular","q":"Rewrite \\(\\dfrac{x}{x-2}\\) with denominator \\((x-2)(x+3)\\).","answer":"\\(\\dfrac{x(x+3)}{(x-2)(x+3)}\\)","solution":"Multiply by the disguised form of 1: \\(\\dfrac{x+3}{x+3}\\)."},{"type":"regular","q":"Rewrite \\(\\dfrac{2}{x+1}\\) with denominator \\((x+1)(x-4)\\).","answer":"\\(\\dfrac{2(x-4)}{(x+1)(x-4)}\\)","solution":"Multiply numerator and denominator by \\((x-4)\\)."},{"type":"regular","q":"Rewrite \\(\\dfrac{3}{4}\\) with denominator 12.","answer":"\\(\\dfrac{9}{12}\\)","solution":"Multiply numerator and denominator by 3."},{"type":"regular","q":"Rewrite \\(\\dfrac{a}{a+2}\\) with denominator \\((a+2)(a-1)\\).","answer":"\\(\\dfrac{a(a-1)}{(a+2)(a-1)}\\)","solution":"Multiply by \\(\\dfrac{a-1}{a-1}\\)."},{"type":"regular","q":"Rewrite \\(\\dfrac{7}{x}\\) with denominator \\(x(x+5)\\).","answer":"\\(\\dfrac{7(x+5)}{x(x+5)}\\)","solution":"Multiply numerator and denominator by \\((x+5)\\)."},{"type":"regular","q":"Rewrite \\(\\dfrac{4}{5}\\) with denominator 35.","answer":"\\(\\dfrac{28}{35}\\)","solution":"Multiply numerator and denominator by 7."},{"type":"regular","q":"Rewrite \\(\\dfrac{x+1}{x}\\) with denominator \\(x(x-3)\\).","answer":"\\(\\dfrac{(x+1)(x-3)}{x(x-3)}\\)","solution":"Multiply by \\(\\dfrac{x-3}{x-3}\\)."},{"type":"word","q":"A fraction of flour is \\(\\dfrac{2}{3}\\). Express it with denominator 18.","answer":"\\(\\dfrac{12}{18}\\)","solution":"Multiply numerator and denominator by 6."},{"type":"word","q":"A ratio \\(\\dfrac{x}{x+1}\\) needs to be rewritten with denominator \\((x+1)(x+2)\\). What is it?","answer":"\\(\\dfrac{x(x+2)}{(x+1)(x+2)}\\)","solution":"Multiply by the disguised form of 1: \\(\\dfrac{x+2}{x+2}\\)."},{"type":"word","q":"A rate \\(\\dfrac{5}{x}\\) is rewritten with denominator \\(x(x-6)\\). What is the result?","answer":"\\(\\dfrac{5(x-6)}{x(x-6)}\\)","solution":"Multiply numerator and denominator by \\((x-6)\\)."},{"type":"word","q":"Express \\(\\dfrac{3}{8}\\) with denominator 40.","answer":"\\(\\dfrac{15}{40}\\)","solution":"Multiply numerator and denominator by 5."},{"type":"word","q":"A concentration \\(\\dfrac{x}{2x+1}\\) is rewritten with denominator \\((2x+1)(x-3)\\). What is it?","answer":"\\(\\dfrac{x(x-3)}{(2x+1)(x-3)}\\)","solution":"Multiply by \\(\\dfrac{x-3}{x-3}\\)."},{"type":"word","q":"Rewrite \\(\\dfrac{1}{x-5}\\) with denominator \\((x-5)(x+7)\\).","answer":"\\(\\dfrac{x+7}{(x-5)(x+7)}\\)","solution":"Multiply numerator and denominator by \\((x+7)\\)."},{"type":"word","q":"A recipe uses \\(\\dfrac{6}{x}\\) cups. Rewrite with denominator \\(x(x+4)\\).","answer":"\\(\\dfrac{6(x+4)}{x(x+4)}\\)","solution":"Multiply by \\(\\dfrac{x+4}{x+4}\\)."}]);
